import{cycleData,fieldCounts,sampleSchedule,transectData,mean}from './eco2-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tx=(x,y,s,n=17,c='#f8f4ed')=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;
const path=(d,c='#b7cac5',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const box=(x,y,w,h,c='#304e5e')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12" fill="${c}" stroke="#a6beb8"/>`;
export const eco2SVG=(a,label)=>`<svg viewBox="0 0 560 440" role="img" aria-label="${esc(label)}">${a}</svg>`;
const plant=(x,y,k=1)=>`<ellipse cx="${x}" cy="${y+5*k}" rx="${9*k}" ry="${3*k}" fill="#122d38" opacity=".5"/><ellipse cx="${x-3*k}" cy="${y}" rx="${7*k}" ry="${3*k}" fill="#a7c5ad" transform="rotate(30 ${x} ${y})"/><ellipse cx="${x+3*k}" cy="${y}" rx="${7*k}" ry="${3*k}" fill="#c1d0b8" transform="rotate(-30 ${x} ${y})"/><circle cx="${x}" cy="${y}" r="${2*k}" fill="#e1b99a"/>`;
export function feedingFigure(p=0){let a=tx(280,30,'Follow food towards its consumer',23),xs=[75,210,345,480],labels=['Producer','Primary','Secondary','Tertiary'];for(let[i,x]of xs.entries()){a+=`<ellipse cx="${x}" cy="200" rx="42" ry="13" fill="#102b38" opacity=".4"/><circle cx="${x}" cy="160" r="39" fill="${i?'#668396':'#678979'}" stroke="#d6d9c6" stroke-width="2"/>`+tx(x,242,labels[i],16)+tx(x,276,['Plant','Caterpillar','Bird','Hawk'][i],16);if(i===0)a+=plant(x,160,2);else if(i===1)for(let j=0;j<4;j++)a+=`<circle cx="${x-20+j*12}" cy="160" r="9" fill="#d1be95"/>`;else a+=`<path d="M${x-24} 165q8 -31 30 -12l20 3 -19 8q-8 18 -31 1" fill="#e2c6a2"/>`;if(i<3)a+=path(`M${x+46} 160h40m-10 -8l10 8 -10 8`);}let q=Math.max(0,Math.min(1,p)),x=75+q*405;a+=`<circle cx="${x}" cy="160" r="7" fill="#f38d75"/>`;return eco2SVG(a+tx(280,345,'Photosynthesis supplies organic molecules and biomass',17)+tx(280,390,'Arrow = transfer of food/material and energy',16)+tx(280,425,'Original symbolic chain · flow speed is not a biological rate',13),'Plant producer → caterpillar primary consumer → bird secondary consumer → hawk tertiary consumer. Arrows point from food towards consumer; moving signal represents transfer, not an organism turning into another.');}
export function cycleFigure({prey=cycleData.prey,predator=cycleData.predator,max=20,phase}={}){max=Number.isFinite(max)&&max>0?max:20;let a=tx(280,28,'Plot population against model time',22)+path('M65 80V330H505');for(let i=0;i<=4;i++)a+=tx(85+i*100,354,String(i),14);for(let i=0;i<=4;i++){let n=max*i/4;a+=tx(40,335-i*60,String(n),13)+path(`M65 ${330-i*60}H505`,'#ffffff16',1);}let outside=false;for(let[k,values,c]of[['prey',prey,'#ebba96'],['predator',predator,'#b0ced1']]){let points=[];for(let i=0;i<5;i++){let v=values?.[i],valid=v!==''&&v!==undefined&&Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=max;if(!valid){if(v!==''&&v!==undefined)outside=true;points.push(null);continue;}let x=85+i*100,y=330-Number(v)/max*240;points.push([x,y]);a+=`<circle cx="${x}" cy="${y}" r="${phase===i?8:5}" fill="${c}"/>`+tx(x,y-12,String(v),12,c);}for(let i=0;i<4;i++)if(points[i]&&points[i+1])a+=path(`M${points[i][0]} ${points[i][1]}L${points[i+1][0]} ${points[i+1][1]}`,c,2);}
a+=tx(280,390,'Time / model units · vertical axis: individuals',16)+tx(280,416,'Peach: prey · pale blue: predators',14);if(outside)a+=tx(280,70,'Some points are outside this scale',14,'#efb69c');return eco2SVG(a,'Original paired population graph, time0–4. Prey values '+prey.join(',')+'; predators '+predator.join(',')+'. Vertical maximum '+max+'. Input points outside scale are omitted. Not measured ecological rates.');}
export function adaptationFigure(p=0){let night=p>=.5,x=night?290+(p-.5)*230:170,a=tx(280,28,'An existing behaviour changes exposure',22)+box(25,75,510,270,night?'#22374f':'#79634f');a+=night?`<circle cx="455" cy="115" r="24" fill="#d4dacb"/><circle cx="466" cy="107" r="22" fill="#22374f"/>`:`<circle cx="455" cy="115" r="25" fill="#e9c991"/>`;a+=`<path d="M40 300L150 155 250 300" fill="#314e53"/>`+tx(149,329,'Shelter',16)+`<ellipse cx="${x}" cy="270" rx="42" ry="17" fill="#c19a7a"/><path d="M${x+25} 269l12 -29 13 20 9 -17 4 30z" fill="#e2bb96"/><path d="M${x-32} 270q-42 -30 -50 -8l40 22" fill="#d2af88"/>`+path(`M${x-20} 281v13m35 -13v13`,'#e2bb96',4);a+=tx(280,382,night?'Cooler night: forage using existing capabilities':'Hot day: shelter rather than forage',18)+tx(280,410,'This individual does not evolve a new inherited feature',15)+tx(280,432,'Symbolic day/night cycle · not every desert species behaves this way',12);return eco2SVG(a,'Worked behavioural response: a desert animal shelters in daytime heat and forages in cooler night. Existing behaviour, not an individual creating an inherited adaptation by need.');}
export function fieldFigure({placed,samples=[],progress}={}){let a=tx(280,28,'Use the generated sample positions',22),size=73,x0=40,y0=83;for(let n=0;n<4;n++)a+=tx(x0+size*n+size/2,65,String(n+1),15)+tx(20,y0+size*n+size/2,String(n+1),15);for(let y=0;y<4;y++)for(let x=0;x<4;x++){let selected=placed?.x===x&&placed?.y===y,recorded=samples.some(s=>s.x===x&&s.y===y);a+=`<rect x="${x0+x*size}" y="${y0+y*size}" width="${size}" height="${size}" fill="${recorded?'#47665e':'#2f4e46'}" stroke="${selected?'#f1b59a':'#79968a'}" stroke-width="${selected?4:1}"/>`;let n=fieldCounts[y*4+x];for(let j=0;j<n;j++)a+=plant(x0+x*size+13+(j%4)*15,y0+y*size+16+Math.floor(j/4)*20,.65);}if(placed){let n=fieldCounts[placed.y*4+placed.x];a+=box(365,105,170,220)+tx(450,137,'Placed1 m² square',15);for(let j=0;j<n;j++)a+=plant(409+j%3*40,178+Math.floor(j/3)*36,1.5);a+=tx(450,352,'Count whole plants',14);}else a+=tx(444,192,'Choose x/y',17)+tx(444,223,'then place',17);a+=tx(280,405,'4×4 m habitat · each square1 m² · x across, y down',15)+tx(280,430,'One target species · original toy field · not physical fieldwork',13);return eco2SVG(a,'Original4×4 field, columns x1–4 rows y1–4; every cell1 m². Target plants shown as whole rosettes. '+(placed?'Highlighted quadrat at x'+(placed.x+1)+',y'+(placed.y+1)+', containing '+fieldCounts[placed.y*4+placed.x]+' target plants.':'No quadrat placed.')+' Recorded '+samples.length+' samples. Counts and distribution fictional.');}
export function transectFigure({station,recorded,progress}={}){let all=recorded??[0,1,2,3],a=tx(280,28,'Measure distribution along a gradient',22)+box(50,62,460,76,'#426858')+tx(90,51,'Shade',14)+tx(470,51,'Open',14)+path('M70 110H490','#e5c4a0',3);for(let[i,s]of transectData.entries()){let x=80+i*125;a+=`<rect x="${x-17}" y="84" width="34" height="34" fill="none" stroke="${station===i?'#f49c81':'#e3d5b7'}" stroke-width="3"/>`+tx(x,159,s.distance+' m',15);}a+=path('M75 195V345H495');for(let n of[0,4,8])a+=tx(48,350-n*16,n,13);let pts=[];for(let i of all){let s=transectData[i],x=80+i*125,y=345-mean(s.counts)*16;pts.push([x,y]);a+=`<circle cx="${x}" cy="${y}" r="6" fill="#efbb96"/>`+tx(x,y-12,mean(s.counts),15);}pts.sort((a,b)=>a[0]-b[0]);for(let i=0;i<pts.length-1;i++)a+=path(`M${pts[i][0]} ${pts[i][1]}L${pts[i+1][0]} ${pts[i+1][1]}`,'#efbb96',2);a+=tx(280,375,'Distance / m · vertical: mean plants per1 m²',15)+tx(280,406,'Light at stations:20,40,60,80 instrument units',15)+tx(280,430,'Original data · association does not isolate a sole cause',13);return eco2SVG(a,'Original transect stations0,2,4,6 m; light20,40,60,80 instrument units. Recorded means '+all.map(i=>mean(transectData[i].counts)).join(',')+' plants per1m². Three repeated counts per station; not physical fieldwork or sole-cause proof.');}
const evidence={
biotic:['Food availability, predators, pathogens, competition','Survival and reproduction can change','Use supplied context; effects are not guaranteed'],
'biotic-data':['Fictional plant A counts:18 →12 →6','Competitor B counts:2 →8 →14','An association needs further causal evidence'],
'adaptation-structure':['Structural: waxy cuticle reduces water loss','Behavioural: forage during cooler conditions','Functional: concentrate urine to conserve water'],
'adaptation-response-data':['Individual response uses existing capabilities','Population evolution involves inherited variation','Selection operates across generations'],
extremophiles:['High temperature · high pressure · high salt','Vent bacteria can tolerate extreme conditions','One tolerance does not establish every tolerance'],
'sample-data':['Counts2,6,2,6 · mean4 · median4 · modes2/6','Estimated density4/m² × habitat16m² =64','Complete toy field68 · estimate is not exact'],
'sampling-method':['Generated coordinates reduce placement preference','Consistent species, area and boundary rules','More representative samples help assess variation'],
 'transect-method':['State hypothesis, interval, area and factor','Repeat transects; measure relevant alternatives','School risk assessment, hygiene and ethical handling']};
export function eco2Figure(o={}){if(o.concealed)return eco2SVG(tx(280,220,'Predict, then reveal the evidence',22),'Evidence concealed until prediction');if(o.kind==='feeding')return feedingFigure(o.progress??0);if(o.kind==='predator-process')return cycleFigure({phase:Math.min(4,Math.floor((o.progress??0)*5))});if(o.kind==='cycle-data')return cycleFigure(o);if(o.kind==='adaptation-response')return adaptationFigure(o.progress??0);if(o.kind==='field'||o.kind==='sampling-process')return fieldFigure(o);if(o.kind==='transect-data'||o.kind==='transect-process')return transectFigure(o);let rows=evidence[o.kind]||evidence.biotic;return eco2SVG(tx(280,35,'Explain the supplied evidence',22)+rows.map((s,i)=>tx(280,135+i*90,s,17)).join('')+tx(280,430,'Original educational comparison · interpret the stated context',13),'Evidence comparison. '+rows.join('. '));}
